import java.util.Scanner;

public class Main {
    static final int DEPTH = 18;
    static long[] sequenceArray = new long[DEPTH];

    static int findMinSteps(long number, int level) {
        int quotient = (int) (number / sequenceArray[level]);
        number %= sequenceArray[level];

        if (number == 0)
            return level * quotient;
        return level * quotient + Math.min(level + findMinSteps(sequenceArray[level] - number, level - 1),
                findMinSteps(number, level - 1));
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        sequenceArray[0] = 0;
        for (int i = 1; i < DEPTH; i++)
            sequenceArray[i] = sequenceArray[i - 1] * 10 + 1;

        while (scanner.hasNextLong()) {
            long val = scanner.nextLong();
            System.out.println(findMinSteps(val, DEPTH - 1));
        }
        scanner.close();
    }
}
